import logging
import re
import time
from collections import namedtuple
from ta_messaging.message_sources.message_source_base import MessageSource
from ute_common_abstract_core.network_elem_identification import UeIdentification
from ta_messaging import message_parser
import sys

from ta_messaging.unparsed_message import UnparsedMessage
from ta_messaging.submodule_ute_common_abstract_core.aliases_registry import aliases_registry

if sys.version_info[0] >= 3:
    from queue import Queue, Empty
else:
    from Queue import Queue, Empty


class AndroidFileMessageSource(MessageSource):
    '''
    Specific message source that implements extracting unparsed messages from qcat parsed file
    '''
    ANDROID_QUEUE = '__android_queue'
    _message_payload = re.compile(r'value\s*\S+Message\s*::=.*?^}', re.DOTALL | re.MULTILINE)
    _protocol_type_message_type = re.compile(r'(LTE|NR5G) RRC OTA Packet\s+--\s*\S+\s*/\s*(\S+)')
    _protocol_type_message_type_and_occurrence_time = \
        re.compile(r'(\d{4}\s*\w+\s*\d{1,2}\s*\d+:\d+:\d+\.\d+\s*)\S+\s*\S+\s*(LTE|NR5G) RRC OTA Packet\s+--\s*\S*\s*\/\s*(\S+(?: \w+)*)')
    _msg_tuple = namedtuple(typename='Msg_container_tuple', field_names='payload type occurrence_time protocol')

    def __init__(self, queue, id):
        self.ue_id = id
        super(AndroidFileMessageSource, self).__init__(queue)
        self.source_specific_parser = message_parser.QCatFileMessageParser()
        self.android_messages_queue = Queue()
        self.dequeue_timeout = 0.1
        aliases_registry()[AndroidFileMessageSource.ANDROID_QUEUE] = self.android_messages_queue
        self._start_in_separate_thread()

    def _create_ue_owner(self):
        device_id = int(self.ue_id)
        return UeIdentification.from_type_id_pairs(identifiers=[('android', device_id)], specific_for_tool='android')

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        return 'android-{}'.format(self.ue_id)

    def _get_protocol_data(self):
        while self.is_running.is_set():
            try:
                data = self.android_messages_queue.get(timeout=self.dequeue_timeout)
                return data
            except Empty:
                pass
        return None

    def _get_unparsed_messages(self, protocol_data):
        self.logger.debug('{} Starting file parsing at: {}'.format(self, time.time()))
        msgs = self._get_packet_data(protocol_data)
        self.logger.debug('{} Stopped file parsing at: {}'.format(self, time.time()))
        return [self._create_unparsed_message(msg) for msg in msgs]

    def _get_opened_connection(self):
        pass

    def _close_connection(self):
        pass

    def _read(self):
        return self._read_file()

    def _get_packet_data(self, protocol_data):
        self.logger.debug('Received raw protocol data: {}'.format(len(protocol_data)))
        protocol_data = "".join(protocol_data)
        payloads = re.findall(AndroidFileMessageSource._message_payload, protocol_data)
        protocol_and_msgtype_and_time = re.findall(AndroidFileMessageSource._protocol_type_message_type_and_occurrence_time, protocol_data)
        self.logger.debug('{} After retrieving payloads and types: {} {}'.format(self, len(payloads), len(protocol_and_msgtype_and_time)))
        if len(payloads) == 0:
            self.logger.warn('No messages received for Android UE')
            return []
        else:
            if len(payloads) != len(protocol_and_msgtype_and_time):
                self.logger.error('Could not match number of payload: {} to number of types and times: {}'
                                  .format(len(payloads), len(protocol_and_msgtype_and_time)))
                return []
            else:
                times, protocols, types = list(zip(*protocol_and_msgtype_and_time))
                types = list(types)
                for index, msg_type in enumerate(types):
                    if ' ' in msg_type:
                        types[index] = self._remove_msg_type_spaces(msg_type)
                        self.logger.debug("{} Aligning messages type from: '{}' to : '{}'".format(self, msg_type, types[index]))
                return [AndroidFileMessageSource._msg_tuple(*record) for record in list(zip(payloads, types, times, protocols))]

    def _remove_msg_type_spaces(self, msg_type):
        return re.sub(' ', '', msg_type)

    def _align_android_protocol_type(self, android_protocol):
        mapping = {'LTE': 'rrc',
                   'NR5G': 'nr-rrc'}
        assert android_protocol in mapping, 'Protocol version : {} not found in mapping: {}'.format(android_protocol, mapping)
        return mapping[android_protocol]

    def _create_unparsed_message(self, msg_tuple):
        owner = self._create_ue_owner()
        msg_payload = msg_tuple.payload
        message_type = msg_tuple.type
        occurrence_time = msg_tuple.occurrence_time
        protocol = self._align_android_protocol_type(msg_tuple.protocol)
        (msg, err, debug) = UnparsedMessage.from_asn1value_msg_type(owner=owner,
                                                                    msg_payload=msg_payload,
                                                                    message_type_value_str=message_type,
                                                                    parser=self.source_specific_parser,
                                                                    meta_data_dict={'occurrence_time': occurrence_time,
                                                                                    'protocol': protocol})
        if debug:
            self.logger.debug(debug)
        if err:
            self.logger.error(err)
            messaging_logger = logging.getLogger('messaging')
            messaging_logger.error(err)
        return msg
